#!/usr/bin/env python3
# AI: below section was generated by an AI
"""
Verify a running light recipe by reading the ACTUAL LED pixels back from the device.

Why this exists: /json/state only says what the device *intends* to render. The
product rules for a customer-facing light recipe — "任何时候不能有黑色",
"每个灯珠都应该充分利用", "动态、有层次、约 1 分钟不同光效、默认循环" — can only be
proven from the pixels themselves.

WLED pushes its frame buffer over WebSocket once a client enables live view
(ws.cpp: `root.containsKey("lv")` -> `sendLiveLedsWs()`). The payload is binary:

    [0] = 'L'
    [1] = version (1 = 1D strip, 2 = 2D matrix)
    [2..] = 3 bytes per LED (R, G, B), one entry per LED for a 1D strip

`sendLiveLedsWs()` reads `strip.getPixelColor(i)`, i.e. the frame buffer the
segment blend produced, *before* the global brightness is applied at bus level.
So a black pixel here really means the effect wrote black — exactly the thing we
must not ship.

Usage:
    python3 scripts/verify_live.py                       # 65 s sample (~1 recipe loop)
    python3 scripts/verify_live.py --seconds 20 --rate 2
    python3 scripts/verify_live.py --json                # machine-readable result
    python3 scripts/verify_live.py --no-state            # pixels only, no /json/state polling

Output: JSON with {success, verdict, frames, fps, black_pixels, coverage, ...}
"""
import json
import os
import sys
import time
import urllib.request

SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, SCRIPT_DIR)


def get_wled_ip():
    try:
        from apply_recipe import get_wled_ip as _ip
        return _ip()
    except Exception:
        return ""


def _fetch_state(ip, path="/json/state", timeout=3):
    try:
        with urllib.request.urlopen(f"http://{ip}{path}", timeout=timeout) as r:
            return json.loads(r.read().decode("utf-8"))
    except Exception:
        return {}


def _parse_live_frame(data):
    """Binary live-view frame -> list of (r,g,b) per LED, or None if not one."""
    if not isinstance(data, (bytes, bytearray)) or len(data) < 5:
        return None
    if data[0] != ord("L") or data[1] != 1:
        return None  # not a 1D live-view frame
    body = data[2:]
    return [(body[i], body[i + 1], body[i + 2]) for i in range(0, len(body) - 2, 3)]


def verify_live(seconds=65, rate=4, ip=None, poll_state=True, verbose=True):
    """Sample the real LED output for `seconds` and check the product rules."""
    ip = ip or get_wled_ip()
    if not ip:
        return {"success": False, "message": "WLED IP not configured"}

    try:
        import websocket  # websocket-client
    except ImportError:
        return {"success": False,
                "message": "缺少依赖 websocket-client，请运行: pip install websocket-client"}

    info = _fetch_state(ip, "/json/info")
    device_leds = (info.get("leds") or {}).get("count", 0)
    gw = _fetch_state(ip)
    if not gw.get("on"):
        return {"success": False, "message": "设备当前是关闭状态（on=false），无法验证光效。",
                "device_leds": device_leds}

    try:
        ws = websocket.create_connection(f"ws://{ip}/ws", timeout=5)
    except Exception as e:
        return {"success": False, "message": f"WebSocket 连接失败: {e}"}
    ws.send('{"lv":true}')
    ws.settimeout(0.05)

    start = time.time()
    last_poll = 0.0
    last_sample = 0.0
    sample_interval = 1.0 / max(1, rate)

    frames = 0
    black_pixel_events = 0
    frames_with_black = 0
    worst_frame = None            # (t, black_count)
    ever_lit = set()
    led_count = device_leds or 0
    signatures = []
    state_trace = []              # (t, ps, [fx per live segment], bri, fps)
    # Per-LED smoothness. A wave built from a handful of Solid blocks has a hard
    # colour step at every block boundary (measured ~200-400 summed over RGB),
    # which is what "一格一格往前走" looks like. A native effect rendering at
    # single-LED resolution stays low. Track it so the requirement is testable.
    adj_steps = []                # every adjacent-LED colour step, all frames
    worst_adj_step = 0
    worst_adj_at = None           # which LED boundary (=index i-1 -> i) it was at
    step_by_led = {}              # LED index -> worst step seen at that boundary
    # Temporal smoothness: how far ONE LED's colour travels between consecutive
    # frames. This is what "丝滑" / "一抖一抖" actually means. A block-authored
    # wave or an effect with an INTEGER phase (Gradient, fx 46) holds the crest
    # still for several frames and then jumps a whole LED: per-LED delta is 0,0,
    # 0,...,40. A sub-pixel effect (Shimmer, fx 161) moves every frame: 2,3,2,3.
    # The two are indistinguishable from the spatial (adjacent-LED) metric alone.
    temporal_steps = []           # every per-LED frame-to-frame delta, all frames
    worst_temporal_step = 0
    worst_temporal_at = None
    worst_temporal_t = None
    # The steepest per-frame jumps, with the timestamp they happened at. If they
    # land right on a scene change (preset switch) the cause is the crossfade
    # length; if they sit in the middle of a scene the cause is the effect itself.
    top_temporal = []             # [(delta, led, t), ...] kept at length <= 5
    # STALL: how often the whole picture is byte-identical to the previous frame.
    # An effect whose phase is an integer LED index (Gradient, fx 46) does not
    # move for several frames and then jumps a whole LED — that freeze-then-jump
    # is what "一抖一抖" looks like. Averages hide it (the frozen frames are 0),
    # so it needs its own counter.
    frame_pairs = 0
    stalled_pairs = 0
    prev_parsed = None
    errors = []

    try:
        while time.time() - start < seconds:
            try:
                data = ws.recv()
            except Exception:
                data = None
            now = time.time()
            parsed = _parse_live_frame(data) if data is not None else None
            if parsed:
                frames += 1
                if not led_count:
                    led_count = len(parsed)
                black = 0
                for idx, (r, g, b) in enumerate(parsed):
                    if r == 0 and g == 0 and b == 0:
                        black += 1
                    else:
                        ever_lit.add(idx)
                if black:
                    black_pixel_events += black
                    frames_with_black += 1
                    if worst_frame is None or black > worst_frame[1]:
                        worst_frame = (round(now - start, 2), black)
                if now - last_sample >= sample_interval:
                    last_sample = now
                    signatures.append((round(now - start, 2), hash(bytes(
                        v for px in parsed for v in px))))
                if len(parsed) > 1:
                    steps = [sum(abs(parsed[i][c] - parsed[i - 1][c]) for c in range(3))
                             for i in range(1, len(parsed))]
                    adj_steps.extend(steps)
                    mx = max(steps)
                    if mx > worst_adj_step:
                        worst_adj_step = mx
                        worst_adj_at = steps.index(mx) + 1
                    # Keep the worst step per LED boundary. If the big steps all
                    # cluster at a few indices, the cause is a seam in the
                    # geometry (segment boundary, mirror fold, offset wrap);
                    # if they are spread out, the cause is the effect's own
                    # contrast (e.g. Pacifica's hard-threshold whitecaps).
                    for idx, st in enumerate(steps, start=1):
                        if st > step_by_led.get(idx, 0):
                            step_by_led[idx] = st

                # Tempoal smoothness (see note above): compare this frame with the
                # previous one, LED by LED.
                if prev_parsed is not None and len(prev_parsed) == len(parsed):
                    frame_pairs += 1
                    if parsed == prev_parsed:
                        stalled_pairs += 1
                    for i in range(len(parsed)):
                        d = (abs(parsed[i][0] - prev_parsed[i][0])
                             + abs(parsed[i][1] - prev_parsed[i][1])
                             + abs(parsed[i][2] - prev_parsed[i][2]))
                        temporal_steps.append(d)
                        if d > worst_temporal_step:
                            worst_temporal_step = d
                            worst_temporal_at = i
                            worst_temporal_t = round(now - start, 2)
                        if d > 40:
                            top_temporal.append((d, i, round(now - start, 2)))
                            if len(top_temporal) > 4000:
                                top_temporal = sorted(top_temporal, reverse=True)[:5]
                prev_parsed = parsed

            if poll_state and now - last_poll >= 1.0:
                last_poll = now
                st = _fetch_state(ip)
                segs = [s for s in (st.get("seg") or []) if s.get("len", 0) > 0]
                state_trace.append({
                    "t": round(now - start, 2),
                    # NOTE: while a playlist is running WLED reports ps = -1; the
                    # playlist cursor lives in "pl". Tracking ps alone makes a
                    # perfectly healthy loop look like it never advanced.
                    "ps": st.get("ps"),
                    "pl": st.get("pl"),
                    "fx": [s.get("fx") for s in segs],
                    "bri": st.get("bri"),
                    "on": st.get("on"),
                    "leds_covered": sum(int(s.get("len", 0)) for s in segs),
                })
    except Exception as e:
        errors.append(str(e))
    finally:
        try:
            ws.send('{"lv":false}')
            ws.close()
        except Exception:
            pass

    elapsed = max(0.001, time.time() - start)

    # -- diagnostics -------------------------------------------------------
    distinct_ps = []
    for row in state_trace:
        if not distinct_ps or distinct_ps[-1] != row["ps"]:
            distinct_ps.append(row["ps"])
    distinct_pl = []
    for row in state_trace:
        if not distinct_pl or distinct_pl[-1] != row["pl"]:
            distinct_pl.append(row["pl"])
    distinct_fx = []
    for row in state_trace:
        key = tuple(row["fx"])
        if not distinct_fx or distinct_fx[-1] != key:
            distinct_fx.append(key)
    distinct_sigs = len(set(s for _, s in signatures))
    # how often the picture actually changed (adjacent signatures differ)
    changes = sum(1 for i in range(1, len(signatures)) if signatures[i][1] != signatures[i - 1][1])
    change_ratio = changes / max(1, len(signatures) - 1)

    coverage = (len(ever_lit) / led_count) if led_count else 0.0
    unpacked = sorted(set(range(led_count)) - ever_lit) if led_count else []
    min_covered = min((r.get("leds_covered", 0) for r in state_trace), default=None)

    mean_adj = (sum(adj_steps) / len(adj_steps)) if adj_steps else None
    p95_adj = None
    if adj_steps:
        ordered = sorted(adj_steps)
        p95_adj = ordered[min(len(ordered) - 1, int(len(ordered) * 0.95))]

    mean_temporal = (sum(temporal_steps) / len(temporal_steps)) if temporal_steps else None
    p95_temporal = None
    if temporal_steps:
        ordered_t = sorted(temporal_steps)
        p95_temporal = ordered_t[min(len(ordered_t) - 1, int(len(ordered_t) * 0.95))]

    stall_fraction = (stalled_pairs / frame_pairs) if frame_pairs else 1.0

    advanced = None
    if poll_state and state_trace:
        # a loop advanced if the playlist cursor moved, the preset changed, or the
        # segment effect set changed at least once
        advanced = (len(distinct_pl) >= 2 or len(distinct_ps) >= 3 or len(distinct_fx) >= 2)

    checks = {
        "no_black_any_frame": frames_with_black == 0,
        "all_leds_used": bool(led_count) and len(ever_lit) >= led_count,
        "animating": change_ratio > 0.05,
        # 丝滑 = 单颗灯珠在相邻两帧之间只走一小步。阈值来自实测：
        #   波浪（Shimmer 亚像素 + Pacifica）：mean ≈ 2-6，p95 ≈ 10-25  → PASS
        #   整数相位效果（Gradient fx46）：mean ≈ 0 但 p95 出现整灯珠跳变 → FAIL
        #   Solid 色块拼出来的波浪：mean ≈ 20-40，p95 > 80        → FAIL
        "smooth_motion": (mean_temporal is not None and
                          mean_temporal <= 8 and p95_temporal <= 30 and
                          stall_fraction <= 0.05),
        "segments_cover_all_leds": (min_covered is not None and
                                    min_covered >= led_count) if poll_state else None,
        "playlist_advanced": advanced if poll_state else None,
        "pixels_captured": frames > 0,
    }
    failed = [k for k, v in checks.items() if v is False]

    result = {
        "success": not failed and frames > 0,
        "verdict": "PASS" if not failed and frames > 0 else "FAIL",
        "ip": ip,
        "seconds": round(elapsed, 1),
        "device_leds": led_count,
        "frames": frames,
        "fps": round(frames / elapsed, 1),
        "black_pixels": black_pixel_events,
        "frames_with_black": frames_with_black,
        "worst_frame": worst_frame,
        "leds_ever_lit": len(ever_lit),
        "leds_never_lit": unpacked,
        "coverage": round(coverage, 3),
        "min_segment_coverage": min_covered,
        "distinct_samples": len(signatures),
        "distinct_pictures": distinct_sigs,
        "change_ratio": round(change_ratio, 3),
        # 丝滑度（主判据）：同一颗灯珠在相邻两帧之间的 RGB 变化量之和。
        "mean_temporal_colour_step": round(mean_temporal, 2) if mean_temporal is not None else None,
        "p95_temporal_colour_step": p95_temporal,
        "worst_temporal_colour_step": worst_temporal_step,
        "worst_temporal_at_led": worst_temporal_at,
        "worst_temporal_at_seconds": worst_temporal_t,
        "frame_stall_fraction": round(stall_fraction, 3),
        "temporal_jumps_over_40": len(top_temporal),
        "steepest_temporal_jumps": sorted(top_temporal, reverse=True)[:10],
        "preset_change_times": [row["t"] for i, row in enumerate(state_trace)
                                if i and row["ps"] != state_trace[i - 1]["ps"]],
        # 静态相邻色差（诊断用，不阻断）：波浪的泡沫边缘本来就是硬过渡，
        # 判定「是不是色块拼出来的」要看这些陡台阶是否**聚集在几何接缝**上，
        # 而不是看它们的大小。
        "mean_adj_colour_step": round(mean_adj, 1) if mean_adj is not None else None,
        "p95_adj_colour_step": p95_adj,
        "worst_adj_colour_step": worst_adj_step,
        "worst_adj_at_led": worst_adj_at,
        "worst_step_by_led": dict(sorted(step_by_led.items())),
        "playlist_presets_seen": distinct_ps,
        "playlist_cursor_seen": distinct_pl,
        "segment_fx_seen": [list(f) for f in distinct_fx],
        "checks": checks,
        "state_trace": state_trace if poll_state else [],
    }
    if errors:
        result["errors"] = errors
    if verbose:
        result["note"] = (
            "像素来自 WLED 实时视图（设备真实帧缓冲，未经全局亮度缩放）。"
            "black_pixels=0 且 leds_never_lit=[] 即满足「任何时候不能有黑色 / 每个灯珠都被点亮」。"
        )
    return result


def main():
    if "--help" in sys.argv or "-h" in sys.argv:
        print(__doc__)
        sys.exit(0)

    def _opt(name, default):
        if name in sys.argv:
            i = sys.argv.index(name)
            if i + 1 < len(sys.argv):
                return sys.argv[i + 1]
        return default

    seconds = float(_opt("--seconds", 65))
    rate = float(_opt("--rate", 4))
    no_state = "--no-state" in sys.argv

    res = verify_live(seconds=seconds, rate=rate, poll_state=not no_state, verbose=True)
    if "--json" in sys.argv:
        print(json.dumps(res, indent=2, ensure_ascii=False))
    else:
        if not res.get("frames"):
            print(json.dumps(res, indent=2, ensure_ascii=False))
            sys.exit(1)
        print(f"判定: {res['verdict']}   采样 {res['seconds']}s / {res['frames']} 帧 ({res['fps']} fps)")
        print(f"黑色像素: {res['black_pixels']}（出现在 {res['frames_with_black']} 帧）  最差帧: {res['worst_frame']}")
        print(f"点亮灯珠: {res['leds_ever_lit']}/{res['device_leds']}（覆盖 {res['coverage'] * 100:.0f}%）"
              f"  未点亮: {res['leds_never_lit']}")
        print(f"最小分段覆盖: {res['min_segment_coverage']} 颗")
        print(f"画面变化: {res['distinct_pictures']} 种 / 变化率 {res['change_ratio'] * 100:.0f}%")
        if res.get("mean_temporal_colour_step") is not None:
            print(f"丝滑度(帧间): 均值 {res['mean_temporal_colour_step']}"
                  f"  p95 {res['p95_temporal_colour_step']}"
                  f"  最差 {res['worst_temporal_colour_step']} @LED {res['worst_temporal_at_led']}"
                  f"  (单颗灯珠每帧走多少；均值<=8 且 p95<=30 才算丝滑)")
            print(f"静止帧占比: {res.get('frame_stall_fraction', 0) * 100:.1f}%"
                  f"  (>5% 说明画面在「冻结-跳变」，即一抖一抖)")
            jumps = res.get("steepest_temporal_jumps") or []
            if jumps:
                pc = res.get("preset_change_times") or []
                def _near(t):
                    return min((abs(t - p) for p in pc), default=None)
                shown = " ".join(
                    f"{d}@LED{led}(t={t}s" + (f",换场差{n:.1f}s" if (n := _near(t)) is not None else "") + ")"
                    for d, led, t in jumps[:6])
                print(f"  最陡的帧间跳变（{res.get('temporal_jumps_over_40')} 次>40）: {shown}")
        if res.get("mean_adj_colour_step") is not None:
            print(f"相邻色差(诊断): 均值 {res['mean_adj_colour_step']}  p95 {res['p95_adj_colour_step']}"
                  f"  最差 {res['worst_adj_colour_step']} @LED {res['worst_adj_at_led']}"
                  f"  (泡沫边缘天然偏硬，只看是否聚集在接缝)")
            byled = res.get("worst_step_by_led") or {}
            if byled:
                hot = sorted(byled.items(), key=lambda kv: -kv[1])[:10]
                print("  最陡的 10 个位置: " +
                      " ".join(f"LED{i}={v}" for i, v in sorted(hot)))
        if not no_state:
            print(f"预设序列 ps: {res['playlist_presets_seen']}")
            print(f"播放列表游标 pl: {res['playlist_cursor_seen']}")
            print(f"分段效果序列 fx: {res['segment_fx_seen']}")
        for k, v in res["checks"].items():
            print(f"  [{'OK ' if v else 'BAD'}] {k}")
        if res.get("warnings"):
            for w in res["warnings"]:
                print("WARN:", w)
    sys.exit(0 if res.get("success") else 1)


if __name__ == "__main__":
    main()
# AI: end
